import UIKit
import SceneKit

// Original artwork, laid out in phone points. Navigation keeps one scene and hero alive.
final class OriginalMenuShell:UIView {
    weak var owner:GameController?
    let paper=UIImageView(image:OriginalUIArt.image("background/bg.png")),banner=UIImageView(image:OriginalUIArt.image("background/banner.png")),logo=UIImageView(image:OriginalUIArt.image("background/logo.png"))
    let submenu=UIImageView(image:OriginalUIArt.image("background/submenu-bg.png")),stats=UIImageView(image:OriginalUIArt.image("background/level-background.png")),play=UIButton(type:.custom),resumeLabel=ComicLabel()
    let hero=SCNView(),heroName=UIButton(type:.custom),xp=OriginalXPBar(),level=UILabel(),currencies=(0..<3).map{_ in UIImageView()},balances=(0..<3).map{_ in UILabel()}
    let content=UIView(),home=UIScrollView(),heading=ComicLabel(),body=UILabel(),homeFrame=UIImageView(image:OriginalUIArt.image("panels/01_bgframesmall.png")?.resizableImage(withCapInsets:UIEdgeInsets(top:40,left:12,bottom:12,right:12)))
    let bottom=UIImageView(image:OriginalUIArt.image("panels/04_bgframe.png")?.resizableImage(withCapInsets:UIEdgeInsets(top:10,left:10,bottom:10,right:10))),equipment=(0..<3).map{_ in UIButton(type:.custom)}
    var tabs:[UIButton]=[],sections:[UIButton]=[],modes:[UIButton]=[]
    var inventory:WardrobeController?,careerPanel:CareerController?
    var selectedTab="Home",selectedSection="Appearance",resume=false,result:String?
    var renderedFaction:Int?,renderedLoadout:HeroLoadout?,renderedWeapon:Int?,sceneBuilds=0
    init(owner:GameController,resume:Bool,result:String?){
        self.owner=owner;self.resume=resume;self.result=result;super.init(frame:owner.view.bounds);backgroundColor=UIColor(red:0.86,green:0.83,blue:0.72,alpha:1)
        for v in [paper,banner,submenu,stats,logo,hero,heroName,xp,level,content,bottom,play,resumeLabel]+currencies+balances+equipment {addSubview(v)}
        for image in [logo]+currencies {image.contentMode = .scaleAspectFit}
        play.setImage(OriginalUIArt.image("components/buttonplaynow_en.png"),for:.normal);play.addAction(UIAction{[weak self] _ in self?.deploy()},for:.touchUpInside)
        resumeLabel.isUserInteractionEnabled=false;resumeLabel.write("RESUME",size:15)
        for name in ["Home","My Stuff","Store","Friends","Options"] {let b=button(name,size:18);b.setBackgroundImage(nil,for:.normal);b.addAction(UIAction{[weak self] _ in self?.selectTab(name)},for:.touchUpInside);addSubview(b);tabs.append(b)}
        for (i,name) in ["Appearance","Weapons","Abilities","Emotes","Widgets","Missions"].enumerated(){let b=button(name,size:16);b.setBackgroundImage(nil,for:.normal);b.isEnabled=i != 3 && i != 4;b.alpha=b.isEnabled ? 1 : 0.45;b.addAction(UIAction{[weak self] _ in self?.openSection(i)},for:.touchUpInside);addSubview(b);sections.append(b)}
        hero.backgroundColor = .clear;hero.isOpaque=false;hero.isPlaying=true;hero.antialiasingMode = .multisampling2X
        hero.addGestureRecognizer(UIPanGestureRecognizer(target:self,action:#selector(turn(_:))))
        heroName.addAction(UIAction{[weak self] _ in self?.chooseHero()},for:.touchUpInside);heroName.titleLabel?.font=OriginalFont.heavy(14);heroName.setTitleColor(.black,for:.normal)
        for l in [level]+balances {l.font=OriginalFont.heavy(15);l.textColor=UIColor(white:0.12,alpha:1)}
        for (i,path) in ["icons/currency_hp.png","icons/currency_vp.png","icons/currency_bf.png"].enumerated(){currencies[i].image=OriginalUIArt.image(path)}
        home.backgroundColor = .clear;content.addSubview(home);home.addSubview(homeFrame);home.addSubview(heading);home.addSubview(body);body.numberOfLines=0;body.font=OriginalFont.heavy(15);body.textColor=UIColor(white:0.15,alpha:1);body.textAlignment = .center
        for mode in Mode.allCases {let b=button(mode.rawValue,size:16);b.addAction(UIAction{[weak self] _ in guard let self=self else{return};self.owner?.selectedMode=mode;self.refresh()},for:.touchUpInside);home.addSubview(b);modes.append(b)}
        for (i,b) in equipment.enumerated(){b.setBackgroundImage(OriginalUIArt.image("panels/04_fgslotframe.png"),for:.normal);b.imageView?.contentMode = .scaleAspectFit;b.imageEdgeInsets=UIEdgeInsets(top:3,left:5,bottom:10,right:5);b.accessibilityLabel=i<2 ? "Weapon \(i+1)" : "Ability";b.addAction(UIAction{[weak self] _ in if i<2 {self?.openInventory(category:11,shop:false);self?.inventory?.slots.selectedSegmentIndex=i;self?.inventory?.refreshList()}else{self?.openCareer()}},for:.touchUpInside)}
        setupScene();updateHero();refresh()
    }
    required init?(coder:NSCoder){fatalError()}
    func button(_ title:String,size:CGFloat)->UIButton{let b=UIButton(type:.custom);b.setBackgroundImage(OriginalUIArt.image("components/button.png")?.resizableImage(withCapInsets:UIEdgeInsets(top:7,left:8,bottom:7,right:8)),for:.normal);b.setTitle(title,for:.normal);b.setTitleColor(.white,for:.normal);b.titleLabel?.font=OriginalFont.heavy(size);b.titleLabel?.adjustsFontSizeToFitWidth=true;b.titleLabel?.minimumScaleFactor=0.85;return b}
    override func layoutSubviews(){
        super.layoutSubviews();paper.frame=bounds
        let safe=bounds.inset(by:safeAreaInsets),x=safe.minX+8,w=safe.width-16,top=safe.minY+4
        banner.frame=CGRect(x:0,y:0,width:bounds.width,height:top+48);logo.frame=CGRect(x:x,y:top+3,width:80,height:36)
        let navX=x+88,navW=w-164;for(i,b) in tabs.enumerated(){b.frame=CGRect(x:navX+CGFloat(i)*navW/5,y:top,width:navW/5,height:44)}
        play.frame=CGRect(x:x+w-68,y:top,width:64,height:64);resumeLabel.frame=CGRect(x:play.frame.minX-3,y:play.frame.maxY-19,width:70,height:25)
        submenu.frame=CGRect(x:0,y:top+48,width:bounds.width,height:44);let subW=(w-76)/6;for(i,b) in sections.enumerated(){b.frame=CGRect(x:x+CGFloat(i)*subW,y:top+48,width:subW,height:44)}
        stats.frame=CGRect(x:x,y:top+96,width:w,height:36);heroName.frame=CGRect(x:x+5,y:top+92,width:w*0.27,height:44);level.frame=CGRect(x:x+w*0.28,y:top+103,width:24,height:22);xp.frame=CGRect(x:x+w*0.28+25,y:top+104,width:w*0.17,height:24)
        let currencyX=x+w*0.52,currencyW=w*0.15;for i in 0..<3 {currencies[i].frame=CGRect(x:currencyX+CGFloat(i)*currencyW,y:top+97,width:34,height:34);balances[i].frame=CGRect(x:currencyX+CGFloat(i)*currencyW+36,y:top+105,width:currencyW-37,height:22)}
        let footerY=safe.maxY-62,contentY=top+138,contentH=max(80,footerY-contentY-6),previewW=min(240,w*0.27)
        hero.frame=CGRect(x:x,y:contentY,width:previewW,height:contentH);content.frame=CGRect(x:x+previewW+10,y:contentY,width:w-previewW-10,height:contentH)
        home.frame=content.bounds;let cw=content.bounds.width;homeFrame.frame=CGRect(x:0,y:0,width:cw,height:max(contentH,158));heading.frame=CGRect(x:8,y:0,width:cw-16,height:28);body.frame=CGRect(x:10,y:31,width:cw-20,height:34)
        for(i,b) in modes.enumerated(){b.frame=CGRect(x:CGFloat(i%2)*(cw/2)+6,y:70+CGFloat(i/2)*46,width:cw/2-12,height:44)};home.contentSize=CGSize(width:cw,height:162)
        inventory?.view.frame=content.bounds;careerPanel?.view.frame=content.bounds
        bottom.frame=CGRect(x:x,y:footerY,width:w,height:60);let slotW=min(110,(w-20)/3);for(i,b) in equipment.enumerated(){b.frame=CGRect(x:x+w/2-slotW*1.5+CGFloat(i)*slotW,y:footerY+3,width:slotW-6,height:54)}
    }
    func setupScene(){let scene=SCNScene();scene.background.contents=UIColor.clear;hero.scene=scene;sceneBuilds+=1;let camera=SCNNode();camera.camera=SCNCamera();camera.camera?.usesOrthographicProjection=true;camera.camera?.orthographicScale=1.1;camera.position=SCNVector3(0,1.1,4);camera.look(at:SCNVector3(0,1.0,0));scene.rootNode.addChildNode(camera);hero.pointOfView=camera;let ambient=SCNNode();ambient.light=SCNLight();ambient.light?.type = .ambient;ambient.light?.intensity=900;scene.rootNode.addChildNode(ambient);let sun=SCNNode();sun.light=SCNLight();sun.light?.type = .directional;sun.light?.intensity=1000;sun.eulerAngles=SCNVector3(-0.5,-0.4,0);scene.rootNode.addChildNode(sun)}
    func updateHero(previewSlot:Int=0){
        guard let owner=owner,let wardrobe=owner.wardrobe,let original=owner.originalWorld,let directory=Bundle.main.resourceURL?.appendingPathComponent("Assets/Characters") else{return}
        let faction=owner.selectedTeam+1,outfit=wardrobe.load(faction,owner.selectedClass),weapon=outfit.weapons.indices.contains(previewSlot) ? outfit.weapons[previewSlot] : outfit.weapons.first
        do {if renderedFaction != faction || owner.menuActor==nil {owner.menuActor?.node.removeFromParentNode();let a=try AnimatedCharacter(faction==1 ? "royal" : "national",directory:directory);hero.scene?.rootNode.addChildNode(a.node);owner.menuActor=a;renderedLoadout=nil;renderedWeapon=nil};guard let a=owner.menuActor else{return};if renderedLoadout != outfit {try wardrobe.apply(outfit,faction:faction,to:a);renderedLoadout=outfit};if renderedWeapon != weapon {a.bones[44].childNodes.filter{$0.name=="held-weapon"}.forEach{$0.removeFromParentNode()};if let id=weapon,let item=wardrobe.weapons[id],let gun=try? original.model(item.model){gun.name="held-weapon";a.bones[44].addChildNode(gun);a.weaponPose=item.pose ?? "smg"};renderedWeapon=weapon};renderedFaction=faction}catch{body.text="Outfit could not be loaded"}
        refresh()
    }
    @objc func turn(_ g:UIPanGestureRecognizer){owner?.menuActor?.node.eulerAngles.y+=Float(g.translation(in:hero).x)*0.009;g.setTranslation(.zero,in:hero)}
    func refresh(){guard let owner=owner else{return};let p=CareerStore.shared.load(owner.selectedTeam+1,owner.selectedClass);heroName.setTitle("\(owner.selectedTeam==0 ? "Royal" : "National") \(owner.selectedClass.rawValue) ▾",for:.normal);level.text=String(p.level);xp.progress=Float(p.levelFraction);for(i,n) in [p.heroPoints,p.valor,p.funds].enumerated(){balances[i].text=String(n)};heading.write(result ?? (resume ? "Paused" : "Choose your battle"),size:18);body.text=result != nil ? owner.game?.endReason : owner.selectedMode.rules;for(i,b) in tabs.enumerated(){b.setTitleColor(["Home","My Stuff","Store","Friends","Options"][i]==selectedTab ? .yellow : .white,for:.normal)};for(i,b) in sections.enumerated(){b.setTitleColor(["Appearance","Weapons","Abilities","Emotes","Widgets","Missions"][i]==selectedSection ? .yellow : .white,for:.normal)};for(i,b) in modes.enumerated(){b.alpha=Mode.allCases[i]==owner.selectedMode ? 1 : 0.7};resumeLabel.isHidden = !resume;let outfit=owner.wardrobe?.load(owner.selectedTeam+1,owner.selectedClass);for(i,b) in equipment.enumerated(){b.setImage(i<2 && (outfit?.weapons.count ?? 0)>i ? OriginalUIArt.image("weapons/weapon\(outfit!.weapons[i]).tga") : i==2 ? OriginalUIArt.image("abilities/ability\(owner.selectedClass == .soldier ? 2001 : owner.selectedClass == .heavy ? 2011 : 2016).tga") : nil,for:.normal)}}
    func hidePanels(){home.isHidden=true;inventory?.view.isHidden=true;careerPanel?.view.isHidden=true}
    func selectTab(_ tab:String){selectedTab=tab;switch tab{case "My Stuff":openInventory(category:inventory?.category ?? 4,shop:false);case "Store":openInventory(category:inventory?.category ?? 4,shop:true);default:hidePanels();home.isHidden=false;for b in modes{b.isHidden=tab != "Home"};refresh();if tab=="Friends"{heading.write("Friends",size:18);body.text="Offline match • no online friends"};if tab=="Options"{heading.write("Touch controls",size:18);body.text="Drag FIRE to aim and shoot. Jump is on the right. Blue labels are allies; red labels are enemies."}};refreshNavigation()}
    func refreshNavigation(){guard let owner=owner else{return};let p=CareerStore.shared.load(owner.selectedTeam+1,owner.selectedClass);for(i,n) in [p.heroPoints,p.valor,p.funds].enumerated(){balances[i].text=String(n)};for(i,b) in tabs.enumerated(){b.setTitleColor(["Home","My Stuff","Store","Friends","Options"][i]==selectedTab ? .yellow : .white,for:.normal)};for(i,b) in sections.enumerated(){b.setTitleColor(["Appearance","Weapons","Abilities","Emotes","Widgets","Missions"][i]==selectedSection ? .yellow : .white,for:.normal)}}
    func openSection(_ i:Int){switch i{case 0:openInventory(category:4,shop:selectedTab=="Store");case 1:openInventory(category:11,shop:selectedTab=="Store");case 2:openCareer();case 5:openCareer(missions:true);default:break}}
    func openInventory(category:Int,shop:Bool){guard let owner=owner,let wardrobe=owner.wardrobe,let original=owner.originalWorld else{return};selectedTab=shop ? "Store" : "My Stuff";selectedSection=category==11 ? "Weapons" : "Appearance";if inventory==nil {let page=WardrobeController(wardrobe:wardrobe,original:original,faction:owner.selectedTeam+1,kind:owner.selectedClass);page.changed={ [weak self] faction,kind in guard let self=self else{return};self.owner?.selectedTeam=faction-1;self.owner?.selectedClass=kind;self.updateHero(previewSlot:self.inventory?.slots.selectedSegmentIndex ?? 0)};owner.addChild(page);content.addSubview(page.view);page.didMove(toParent:owner);inventory=page};hidePanels();inventory?.shopMode=shop;inventory?.category=category;inventory?.view.isHidden=false;inventory?.refreshList();inventory?.view.frame=content.bounds;refreshNavigation()}
    func openCareer(missions:Bool=false){guard let owner=owner else{return};selectedTab="My Stuff";selectedSection=missions ? "Missions" : "Abilities";if careerPanel?.kind != owner.selectedClass || careerPanel?.faction != owner.selectedTeam+1 {remove(careerPanel);let page=CareerController(faction:owner.selectedTeam+1,kind:owner.selectedClass);page.done={ [weak self] in self?.refreshNavigation() };owner.addChild(page);content.addSubview(page.view);page.didMove(toParent:owner);careerPanel=page};hidePanels();careerPanel?.view.isHidden=false;careerPanel?.view.frame=content.bounds;careerPanel?.refresh();refreshNavigation()}
    func remove(_ page:UIViewController?){page?.willMove(toParent:nil);page?.view.removeFromSuperview();page?.removeFromParent()}
    func detachControllers(){remove(inventory);remove(careerPanel);inventory=nil;careerPanel=nil}
    func chooseHero(){guard let owner=owner else{return};let alert=UIAlertController(title:"Select hero",message:resume ? "Changes apply to your next battle" : nil,preferredStyle:.actionSheet);for faction in 1...2 {for kind in HeroClass.allCases{alert.addAction(UIAlertAction(title:"\(faction==1 ? "Royal" : "National") \(kind.rawValue)",style:.default){[weak self] _ in guard let self=self else{return};owner.selectedTeam=faction-1;owner.selectedClass=kind;UserDefaults.standard.set(faction-1,forKey:"selected-faction");UserDefaults.standard.set(kind.rawValue,forKey:"selected-class");self.inventory?.changeHero(faction:faction,kind:kind);self.updateHero();if self.careerPanel?.view.isHidden==false{self.openCareer()}})}};alert.addAction(UIAlertAction(title:"Cancel",style:.cancel));alert.popoverPresentationController?.sourceView=heroName;owner.present(alert,animated:true)}
    func deploy(){guard let owner=owner else{return};if resume {owner.render.isHidden=false;owner.render.isPlaying=true;owner.scene.isPaused=false;owner.game?.paused=false;owner.last=0;owner.career=CareerStore.shared.load(owner.matchFaction,owner.matchKind);owner.game?.heroes[0].abilityRank=owner.career.abilityRank;detachControllers();removeFromSuperview();owner.menu=nil;owner.menuActor=nil;owner.comicHUD.isHidden=false;owner.scoreToast.isHidden=false;for v in [owner.left,owner.right,owner.fire,owner.skill,owner.pause,owner.jumpButton,owner.crosshair,owner.switchButton,owner.reloadButton]{v.isHidden=false};owner.teamLabels.forEach{$0.isHidden=false}}else{owner.start()}}
}
final class OriginalXPBar:UIView {
    let empty=UIImageView(image:OriginalUIArt.image("components/barxpemptyshorteor.png")),full=UIImageView(image:OriginalUIArt.image("components/barxpfullshorteor.png")),fillMask=CALayer()
    var progress:Float=0 {didSet{setNeedsLayout()}}
    override init(frame:CGRect){super.init(frame:frame);addSubview(empty);addSubview(full);fillMask.backgroundColor=UIColor.white.cgColor;full.layer.mask=fillMask}
    convenience init(){self.init(frame:.zero)}
    required init?(coder:NSCoder){fatalError()}
    override func layoutSubviews(){super.layoutSubviews();empty.frame=bounds;full.frame=bounds;CATransaction.begin();CATransaction.setDisableActions(true);fillMask.frame=CGRect(x:0,y:0,width:bounds.width*CGFloat(max(0,min(1,progress))),height:bounds.height);CATransaction.commit()}
}
